examples:
主循环的结构可表示为：
```cpp
bool done{false};
while (!done) {
    int selection{displayMenu()};
    switch (selection) {
        case 0:
            done = true;
            break;
        case 1:
            doHire(employeeDB);
            break;
        case 2:
            doFire(employeeDB);
            break;
        case 3:
            doPromote(employeeDB);
            break;
        case 4:
            employeeDB.displayAll();
            break;
        case 5:
            employeeDB.displayCurrent();
            break;
        case 6:
            employeeDB.displayFormer();
            break;
        default:
            std::cerr << "Unknown command." << std::endl;
            break;
    }
}
```
